//! Layered tree-oracle comparison (development-time JDK 17 oracle, no JVM at
//! test time).
//!
//! The data file was generated by tools/gen-tree-oracle/GenTreeOracle.java on
//! the baseline JDK 17.0.19 (jdk17u @ 982d53c):
//!   new Pretty(writer, false).printUnit(unit, null)
//! after JavacTask.parse() with -proc:none -XDshould-stop.at=PARSE and
//! keepComments=true.
//!
//! This test parses each recorded source with the ported parser, prints it with
//! the ported Pretty, and compares the text. Records that need syntax which is
//! explicitly not ported yet (S7b: records/sealed/patterns/switch
//! expressions/modules/lambda/method references) are reported as SKIP with the
//! missing-syntax reason; records whose oracle output contains doc comments are
//! skipped because this port currently runs with keepDocComments=false
//! (S8 DocCommentParser classification). Any other difference is a FAIL with the
//! expected-vs-actual diff lines.

use std::panic::AssertUnwindSafe;
use std::rc::Rc;

use javac_strings::JavaString;

use javac_core::code::source::Source;
use javac_core::util::abstract_log::AbstractLog;
use javac_core::compiler_context::CompilerContext;
use javac_core::parser::parser::Parser;
use javac_core::parser::parser_factory::ParserFactory;
use javac_core::parser::scanner_factory::ScannerFactory;
use javac_core::tree::pretty::Pretty;
use javac_core::util::context::Context;
use javac_core::util::log::Log;
use javac_core::util::names::Names;

const TREE_ORACLE: &str = include_str!("../../javac-tests/data/tree-oracle.txt");

struct Record {
    name: String,
    body: String,
}

fn source_path(name: &str) -> Option<String> {
    if let Some(rest) = name.strip_prefix("javac/") {
        Some(format!(
            "reference/jdk17u/test/langtools/tools/javac/{rest}"
        ))
    } else if name.starts_with("samples/") {
        Some(format!("tools/gen-tree-oracle/{name}"))
    } else {
        None
    }
}

fn records() -> Vec<Record> {
    let mut out = Vec::new();
    let mut current: Option<(String, Vec<&str>)> = None;
    for line in TREE_ORACLE.lines() {
        if let Some(rest) = line.strip_prefix("=== FILE: ") {
            let name = rest.strip_suffix(" ===").expect("file marker").to_string();
            current = Some((name, Vec::new()));
        } else if line == "=== END ===" {
            if let Some((name, lines)) = current.take() {
                out.push(Record {
                    name,
                    body: format!("{}\n", lines.join("\n")),
                });
            }
        } else if let Some((_, lines)) = current.as_mut() {
            lines.push(line);
        }
    }
    out
}

fn make_parser() -> (CompilerContext, ParserFactory) {
    let mut context = Context::new();
    let log = Log::instance(&mut context);
    let dummy = Rc::new(
        javac_tools::tools::simple_java_file_object::SimpleJavaFileObject::new(
            javac_tools::uri::URI::create(&JavaString::from("file:///Dummy.java")),
            javac_tools::tools::java_file_object::Kind::SOURCE,
        ),
    );
    log.borrow_mut().use_source(Some(dummy));
    let names = Rc::new(Names::new(false));
    let scanner_factory = ScannerFactory::new(&mut context, names.clone(), Source::DEFAULT);
    let factory = ParserFactory::new(
        &mut context,
        names,
        Source::DEFAULT,
        scanner_factory,
        None,
    );
    (CompilerContext::new(), factory)
}

fn parse_and_print(body: &str, parse_module_info: bool) -> String {
    let (mut ctx, factory) = make_parser();
    let mut parser =
        factory.new_parser_full(
            &mut ctx,
            &JavaString::from(body),
            true,
            true,
            false,
            parse_module_info,
        );
    let tree = parser.parse_compilation_unit(&mut ctx);
    let mut pretty = Pretty::new(false);
    pretty.print_unit(&ctx, tree, None);
    pretty.get_out().to_string_lossy()
}

fn classify_panic(message: &str) -> Option<&'static str> {
    if message.contains("S7b") {
        Some("S7b syntax not ported yet")
    } else if message.contains("S8") || message.contains("keepDocComments") {
        Some("keepDocComments=false (S8 DocCommentParser)")
    } else {
        None
    }
}

#[test]
fn tree_oracle_layered_comparison() {
    let records = records();
    assert_eq!(records.len(), 37, "tree-oracle record count");
    let mut passed = 0usize;
    let mut skipped = 0usize;
    let mut failed = 0usize;
    let mut failures: Vec<String> = Vec::new();
    for record in &records {
        let Some(path) = source_path(&record.name) else {
            skipped += 1;
            println!("SKIP {}: source file path unknown", record.name);
            continue;
        };
        let repo_root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
        let full_path = repo_root.join(&path);
        let source = match std::fs::read_to_string(&full_path) {
            Ok(source) => source,
            Err(error) => {
                skipped += 1;
                println!("SKIP {}: source file unavailable ({full_path:?}: {error})", record.name);
                continue;
            }
        };
        let print_source = source.clone();
        let is_module_info = record.name.contains("module-info");
        let result = std::panic::catch_unwind(AssertUnwindSafe(|| {
            parse_and_print(&print_source, is_module_info)
        }));
        match result {
            Ok(actual) => {
                let expected = record.body.trim_end();
                if actual.trim_end() == expected {
                    passed += 1;
                    println!("PASS {}", record.name);
                } else {
                    failed += 1;
                    let expected_lines: Vec<&str> = expected.lines().collect();
                    let actual_lines: Vec<&str> = actual.trim_end().lines().collect();
                    let mut diffs = Vec::new();
                    let max = expected_lines.len().max(actual_lines.len());
                    for i in 0..max {
                        let e = expected_lines.get(i).copied().unwrap_or("<missing>");
                        let a = actual_lines.get(i).copied().unwrap_or("<missing>");
                        if e != a {
                            diffs.push(format!("line {}: expected {:?} actual {:?}", i + 1, e, a));
                            if diffs.len() >= 10 {
                                break;
                            }
                        }
                    }
                    let message = format!(
                        "FAIL {}: expected-vs-actual diff (first 10 lines):\n{}",
                        record.name,
                        diffs.join("\n")
                    );
                    println!("{message}");
                    failures.push(message);
                }
            }
            Err(payload) => {
                let message = payload
                    .downcast_ref::<String>()
                    .cloned()
                    .or_else(|| payload.downcast_ref::<&str>().map(|s| s.to_string()))
                    .unwrap_or_else(|| "unknown panic".to_string());
                if let Some(reason) = classify_panic(&message) {
                    skipped += 1;
                    println!("SKIP {}: {} ({message})", record.name, reason);
                } else {
                    failed += 1;
                    let message = format!("FAIL {}: parser panic: {message}", record.name);
                    println!("{message}");
                    failures.push(message);
                }
            }
        }
    }
    println!(
        "tree-oracle summary: total={} passed={} skipped={} failed={}",
        records.len(),
        passed,
        skipped,
        failed
    );
    assert!(
        failures.is_empty(),
        "tree-oracle failures ({}):\n{}",
        failures.len(),
        failures.join("\n\n")
    );
}
